package br.com.mikael.nexustech.gui;
import br.com.mikael.nexustech.energy.TileEntityCoalGenerator;import net.minecraft.client.gui.Gui;import net.minecraft.client.gui.inventory.GuiContainer;import net.minecraft.entity.player.InventoryPlayer;
public class GuiCoalGenerator extends GuiContainer{private final TileEntityCoalGenerator te;public GuiCoalGenerator(InventoryPlayer inv,TileEntityCoalGenerator t){super(new ContainerCoalGenerator(inv,t));te=t;xSize=176;ySize=166;}protected void drawGuiContainerForegroundLayer(int mx,int my){fontRenderer.drawString("Gerador a Carvao",8,6,0x404040);fontRenderer.drawString("Combustivel",62,20,0x404040);fontRenderer.drawString("Inventario",8,72,0x404040);fontRenderer.drawString(te.getEnergyStored()+" / "+te.getMaxEnergyStored()+" FE",8,58,0x404040);}protected void drawGuiContainerBackgroundLayer(float p,int mx,int my){drawDefaultBackground();int l=(width-xSize)/2,t=(height-ySize)/2;Gui.drawRect(l,t,l+176,t+166,0xFFC6C6C6);Gui.drawRect(l+4,t+4,l+172,t+162,0xFFE8E8E8);Gui.drawRect(l+7,t+69,l+169,t+72,0xFF555555);int b=(int)(158F*te.getEnergyStored()/te.getMaxEnergyStored());Gui.drawRect(l+9,t+70,l+9+b,t+71,0xFF55AA55);drawSlot(l+79,t+34);for(int r=0;r<3;r++)for(int c=0;c<9;c++)drawSlot(l+7+c*18,t+83+r*18);for(int c=0;c<9;c++)drawSlot(l+7+c*18,t+141);}private void drawSlot(int x,int y){Gui.drawRect(x,y,x+18,y+18,0xFF777777);Gui.drawRect(x+1,y+1,x+17,y+17,0xFF373737);}}